def Strongest_Extension(class_name, extensions):
    def strength(s):
        cap = sm = 0
        for ch in s:
            if ch.isupper():
                cap += 1
            elif ch.islower():
                sm += 1
        return cap - sm

    max_strength = max(strength(e) for e in extensions)
    for e in extensions:
        if strength(e) == max_strength:
            return f"{class_name}.{e}"

